import type { Metadata } from "next";
import {
  DEFAULT_LOCALE,
  getLocaleOpenGraphLanguage,
  getLocaleSchemaLanguage,
  getTranslation,
  SUPPORTED_LOCALES,
  type Locale,
} from "@/lib/i18n";
import { getToolTranslation } from "@/lib/tool-i18n";
import { canonicalUrl, siteConfig } from "@/lib/site-config";

export { canonicalUrl, siteConfig };

// 1200×630 PNG generated by scripts/generate-icons.mjs. Social networks do
// not render SVG og:images, so the preview card has to be a raster asset.
export const defaultOpenGraphImage = "/og-image.png";
const openGraphImageWidth = 1200;
const openGraphImageHeight = 630;

/** Sentence-closing marks that already appear at the end of a subtitle. */
const SENTENCE_MARKS = /[.!?…。！？।]/;

/** The terminator that reads naturally in the locale's own script. */
function sentenceMark(locale: Locale): string {
  if (locale === "ja" || locale === "zh-CN" || locale === "zh-TW") return "。";
  if (locale === "hi") return "।";
  return ".";
}

/** Ensures a catalog sentence ends with a mark without producing "。.". */
function asSentence(value: string, locale: Locale): string {
  const text = value.trim();
  return SENTENCE_MARKS.test(text) ? text : `${text}${sentenceMark(locale)}`;
}

export function getSiteDescription(locale: Locale): string {
  const t = getTranslation(locale);
  const toolT = getToolTranslation(locale);
  // CJK and Hindi subtitles already end with their own sentence mark; only
  // add one where the catalog has none, so no locale ends up with "。.".
  return [
    asSentence(t.homeSubtitle, locale),
    asSentence(toolT.dnsSubtitle, locale),
    asSentence(toolT.pingSubtitle, locale),
    asSentence(toolT.reputationSubtitle, locale),
  ].join(" ");
}

