export function getHomeSeoTitle(locale: Locale): string {
  return homeSeoTitles[locale] ?? getTranslation(locale).homeTitle;
}

/**
 * A compact homepage description built from existing catalog sentences, so
 * every locale gets a specific snippet without a second translation catalog.
 */
export function getHomeDescription(locale: Locale): string {
  const t = getTranslation(locale);
  return `${asSentence(t.homeSubtitle, locale)} ${asSentence(t.checkSubtitle, locale)}`;
}

export function getSiteKeywords(locale: Locale): string[] {
  const t = getTranslation(locale);
  const toolT = getToolTranslation(locale);
  return [
    t.homeTitle,
    t.checkTitle,
    toolT.asnTitle,
    toolT.dnsTitle,
    toolT.whoisTitle,
    toolT.cdnTitle,
    toolT.pingTitle,
    toolT.reputationTitle,
    "ASN",
    "BGP",
    "DNS",
    "WHOIS",
    "CDN",
    "IPv4",
    "IPv6",
    "PeeringDB",
  ];
}

function getOpenGraphImageAlt(locale: Locale): string {
  return `${siteConfig.name} – ${getToolTranslation(locale).brandTagline}`;
}

/** Schema.org `inLanguage` tags for every UI locale, using the central registry. */
export const schemaInLanguage = SUPPORTED_LOCALES.map((locale) =>
  getLocaleSchemaLanguage(locale),
);

/**
 * Absolute document title. Next.js `title.template` is not applied to
 * `app/page.tsx`. A title that already *is* the site name is not suffixed,
 * which would read "IP Info | IP Info".
 */
export function documentTitle(title: string): string {
  return title === siteConfig.name ? title : `${title} | ${siteConfig.name}`;
}


export function createPageMetadata({
  title,
  description,
  path = "/",
  keywords = [],
  locale = DEFAULT_LOCALE,
  index = true,
}: {
  title: string;
  description: string;
  path?: string;
  keywords?: string[];
  locale?: Locale;
  /**
   * Set to false for parameterized routes that render a generic fallback
   * (for example an invalid `/asn/[asn]` deep link). The canonical URL still
   * points at the parent tool so users keep a valid navigation target.
   */
  index?: boolean;
}): Metadata {
  const canonical = canonicalUrl(path);

  return {
    title: {
      absolute: documentTitle(title),
    },
    description,
    keywords: [...getSiteKeywords(locale), ...keywords],
    applicationName: siteConfig.name,
    authors: [{ name: siteConfig.name, url: siteConfig.url }],
    creator: siteConfig.name,
    publisher: siteConfig.name,
    category: "technology",
    formatDetection: {
      telephone: false,
      email: false,
      address: false,
    },
    alternates: {
      // The app intentionally has one canonical URL per route. Locale is
      // negotiated from Accept-Language and an explicit functional cookie;
      // emitting hreflang URLs for non-existent locale paths would be false.
      canonical,
      types: {
        "text/plain": `${siteConfig.url}/llms.txt`,
      },
    },
    robots: index
      ? {
          index: true,
          follow: true,
          googleBot: {
            index: true,
            follow: true,
            "max-image-preview": "large",
            "max-snippet": -1,
            "max-video-preview": -1,
          },
        }
      : {
          index: false,
          follow: true,
          googleBot: {
            index: false,
            follow: true,
            noimageindex: true,
          },
        },
    openGraph: {
      type: "website",
      locale: getLocaleOpenGraphLanguage(locale),
      url: canonical,
      title,
      description,
      siteName: siteConfig.name,
      images: [
        {
          url: defaultOpenGraphImage,
          width: openGraphImageWidth,
          height: openGraphImageHeight,
          alt: getOpenGraphImageAlt(locale),
          type: "image/png",
        },
      ],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [
        {
          url: defaultOpenGraphImage,
          width: openGraphImageWidth,
          height: openGraphImageHeight,
          alt: getOpenGraphImageAlt(locale),
          type: "image/png",
        },
      ],
    },
  };
}
